from __future__ import annotations

import ast
from dataclasses import dataclass
from pathlib import Path


@dataclass(slots=True, frozen=True)
class ImportRecord:
    """Immutable record of a single import statement."""
    module: str
    alias: str | None
    is_star_import: bool


def extract_imports(source: bytes) -> list[ImportRecord]:
    """Extract all top-level import modules and their assigned aliases from source bytes."""
    tree = ast.parse(source.decode("utf-8"), filename="<string>")
    records: list[ImportRecord] = []

    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                records.append(
                    ImportRecord(
                        module=alias.name,
                        alias=alias.asname,
                        is_star_import=False,
                    )
                )
        elif isinstance(node, ast.ImportFrom):
            module = node.module or ""
            level = node.level
            if level > 0:
                continue  # Skip relative imports (e.g. `from .pkg import x`)
            for alias in node.names:
                if alias.name == "*":
                    records.append(
                        ImportRecord(module=module, alias=None, is_star_import=True)
                    )
                    continue
                records.append(
                    ImportRecord(
                        module=module,
                        alias=alias.asname,
                        is_star_import=False,
                    )
                )
    return records
```

### Guarantees
- **Zero runtime dependencies**: Uses only `ast` and `dataclasses` from the standard library.
- **POSIX-safe paths**: Returns `pathlib.Path` objects without platform-specific separators.
- **Deterministic traversal**: Processes `Import` and `ImportFrom` nodes in document order with `O(1)` memory per record.
